"""Build student pages from the actual TypeScript implementation."""
from pathlib import Path
from html import escape
import hashlib,json,shutil

APP=Path(__file__).resolve().parents[1]
ROOT=APP.parents[1]
PUBLIC=APP/'public';PUBLIC.mkdir(exist_ok=True)
SOURCE=ROOT/'lesson-c01/lesson-c01-app/public'
for name in ['astronaut.png','prism.js','prism-LICENSE.txt','code-highlighting.js','code-highlighting.css']:
 if SOURCE.is_dir() and (SOURCE/name).resolve() != (PUBLIC/name).resolve():
  shutil.copyfile(SOURCE/name,PUBLIC/name)
 elif not (PUBLIC/name).exists():
  raise FileNotFoundError('Required bundled visual asset: '+name)

STYLE='''
.chart-row{margin:18px 0;font-size:22px}.chart-bar{height:30px;border-radius:9px;background:linear-gradient(90deg,#087fff,#8838ff);min-width:2px;margin-top:8px}.actions{display:flex;gap:12px;flex-wrap:wrap}.table{overflow:auto}#query-rows td{white-space:normal}#question{min-height:125px}

:root{font-family:Inter,"Segoe UI",Arial,sans-serif;font-size:21px;line-height:1.65;color:#101a44;background:#f4f9ff;--paper:#fff;--ink:#101a44;--muted:#405780;--line:#d4e5fa;--soft:#eaf5ff;--navy:#102544}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 100% 0,#e1f1ff,transparent 35%),#f4f9ff;color:var(--ink)}main{max-width:1480px;margin:auto;padding:32px clamp(20px,4vw,64px) 64px}a{color:#006bd6}h1,h2,h3{line-height:1.15;color:var(--ink)}h1{font-size:clamp(40px,4.5vw,64px);letter-spacing:-.04em;margin:16px 0 24px}h1 em{font-style:normal;color:#ee5425}h2{font-size:34px;margin:0 0 22px}h3{font-size:25px;margin:0 0 16px}p{margin:14px 0 22px}.brand{display:flex;justify-content:space-between;gap:24px;align-items:center;flex-wrap:wrap;font-weight:800}.brand a{text-decoration:none;color:var(--ink)}.brand span{color:#087fff}.badge{font-size:18px;background:var(--soft);border:1px solid var(--line);padding:10px 20px;border-radius:40px}.hero{display:grid;grid-template-columns:1fr 190px;align-items:center;gap:40px;margin:46px 0 32px}.hero img{width:190px}.eyebrow{font-size:18px;letter-spacing:.09em;font-weight:800;color:#087fff}.lead{font-size:24px;color:var(--muted);max-width:1050px}.nav{display:flex;gap:12px;flex-wrap:wrap;padding:18px;border-radius:22px;background:var(--soft);border:1px solid var(--line);margin:24px 0 36px}.nav a,.nav button,.button,button{font:700 19px/1.45 Inter,"Segoe UI",Arial,sans-serif;border:1px solid var(--line);border-radius:13px;background:var(--paper);color:var(--ink);padding:14px 19px;cursor:pointer;text-decoration:none;min-height:56px}.nav a[aria-current]{background:#087fff;color:#fff;border-color:#087fff}.nav button{margin-left:auto}.button.primary,button.primary{background:#087fff;border-color:#087fff;color:#fff}.button{display:inline-block}button:disabled{opacity:.55;cursor:wait}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px;margin:24px 0}.workspace{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.15fr);gap:24px}.panel,.card,.step{background:var(--paper);border:1px solid var(--line);border-radius:24px;padding:30px;min-width:0}.card:nth-child(3n+2){background:linear-gradient(145deg,#f1ebff,var(--paper))}.card:nth-child(3n){background:linear-gradient(145deg,#e9f8f1,var(--paper))}.step>.number,.card>.number{display:inline-grid;place-items:center;width:48px;height:48px;background:#087fff;color:white;border-radius:50%;font-weight:bold;margin-bottom:20px}.step{margin:26px 0}.step p:last-child{margin-bottom:0}.note{padding:24px 28px;border-left:5px solid #8838ff;border-radius:15px;background:var(--soft);color:var(--muted);margin:26px 0}.flow{display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap;background:var(--soft);border:1px solid var(--line);padding:24px;border-radius:24px;margin:24px 0 34px}.flow b{font-size:23px}.flow span{color:#087fff;font-weight:800}.flow p{font-size:19px;margin:3px 0 0;color:var(--muted)}label{display:block;font-weight:800;margin:22px 0 12px}textarea{width:100%;min-height:175px;resize:vertical;font:22px/1.6 Inter,"Segoe UI",Arial,sans-serif;border:1px solid var(--line);border-radius:16px;padding:20px;background:var(--paper);color:var(--ink)}.meta{font-size:19px;color:var(--muted);overflow-wrap:anywhere}.stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:24px 0}.stat{padding:18px;border:1px solid var(--line);border-radius:16px;background:var(--soft)}.stat span{display:block;font-size:18px;color:var(--muted)}.stat strong{font-size:24px;overflow-wrap:anywhere}#answer{font:22px/1.7 Inter,"Segoe UI",Arial,sans-serif;white-space:pre-wrap;overflow-wrap:anywhere;min-height:165px;background:var(--soft);border-radius:16px;padding:24px}#answer:empty:before{content:"The real assistant answer will appear here.";color:var(--muted)}#events{padding:0;list-style:none;max-height:420px;overflow:auto}#events li{padding:18px 0;border-bottom:1px solid var(--line)}#events strong{display:block;color:#087fff;font-size:20px}#events span{display:block;font-size:19px;color:var(--muted);overflow-wrap:anywhere}.source{font-size:18px;color:var(--muted)}pre{max-width:100%;overflow:auto}code{overflow-wrap:anywhere;font-family:Consolas,"Cascadia Code",monospace}pre code[class*="language-"]{font-size:20px!important;line-height:1.7!important}.diagram{overflow:auto;border:1px solid var(--line);border-radius:20px;background:white;padding:12px}.diagram img{display:block;min-width:1380px;width:100%}.actions{display:flex;gap:14px;flex-wrap:wrap;margin:28px 0}footer{border-top:1px solid var(--line);margin-top:48px;padding-top:24px;font-size:18px;color:var(--muted)}table{border-collapse:collapse;width:100%}td,th{padding:16px;text-align:left;border-bottom:1px solid var(--line);vertical-align:top}.table{overflow:auto}a:focus-visible,button:focus-visible,textarea:focus-visible{outline:3px solid #ff791f;outline-offset:4px}html[data-theme=dark]{color-scheme:dark;--paper:#122342;--ink:#edf5ff;--line:#355071;--soft:#172e51;--muted:#bbcee8;background:#09152b}html[data-theme=dark] body{background:#09152b}html[data-theme=dark] a{color:#8bc7ff}html[data-theme=dark] .nav a[aria-current],html[data-theme=dark] .primary{color:white}html[data-theme=dark] .card{background:var(--paper)}html[data-theme=dark] #events strong{color:#8bc7ff}@media(max-width:850px){.grid,.workspace{grid-template-columns:1fr}.hero{grid-template-columns:1fr}.hero img{display:none}.nav button{margin-left:0}.nav a,.nav button{flex:1 1 200px;text-align:center}.stats{grid-template-columns:1fr}.flow{align-items:flex-start}.panel,.card,.step{padding:24px}.table table{min-width:650px}}
'''
STYLE += '\n:root{overflow-wrap:anywhere}select{width:100%;min-width:0;min-height:58px;font:700 21px/1.45 Inter,"Segoe UI",Arial,sans-serif;padding:14px;border:1px solid var(--line);border-radius:13px;color:var(--ink);background:var(--paper);margin-bottom:18px}#review-plan{font-size:22px;line-height:1.55;max-height:300px;overflow:auto}#review-panel pre{max-height:190px}#configuration-content{white-space:pre-wrap!important;overflow-wrap:anywhere}\n'
STYLE += '\n#questions-container.batch{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.question-card{min-width:0;border:1px solid var(--line);border-radius:18px;padding:22px;margin:18px 0;background:var(--paper)}.question-card legend{font-size:23px;font-weight:800;padding:0 12px}.question-text{font-size:24px;font-weight:700;margin:4px 0 12px}.option-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.question-option{min-width:0;border:1px solid var(--line);border-radius:14px;padding:16px;background:var(--soft)}.option-choice{display:flex;gap:14px;align-items:flex-start;font-size:22px;margin:0;cursor:pointer}.option-choice input,.other-choice input{width:24px;height:24px;flex:0 0 24px;accent-color:#087fff;margin-top:4px}.option-choice strong{display:block;font-size:22px}.option-description{display:block;font-size:20px;line-height:1.45;font-weight:400;margin-top:8px}.other-choice{display:flex;gap:12px;align-items:center;font-size:21px;margin:18px 0 0}.other-text{min-height:80px;margin-top:12px;font-size:21px}.option-preview{margin-top:14px;font-size:20px;line-height:1.4}.option-preview iframe{width:100%;height:210px;border:1px solid var(--line);border-radius:12px;background:white}.option-preview pre{max-height:230px;white-space:pre-wrap}.option-preview pre code{font-size:20px!important;line-height:1.4!important}#question-panel details{font-size:20px;margin:14px 0}#question-panel summary{cursor:pointer}#request-meta{font-size:20px}#question-input{white-space:pre-wrap!important}#answer-summary{white-space:pre-wrap!important}@media(max-width:850px){#questions-container.batch,.option-grid{grid-template-columns:1fr}}\n'
STYLE+='\nhtml body #conversation pre,html body #conversation pre>code[class*="language-"]{white-space:pre-wrap!important;overflow-wrap:anywhere!important;word-break:normal!important;}\n'
(PUBLIC/'style.css').write_text(STYLE,encoding='utf-8')
(PUBLIC/'navigation.js').write_text('''(()=>{const key="agent-sdk-lesson58-theme";try{document.documentElement.dataset.theme=localStorage.getItem(key)||"light"}catch{}const b=document.getElementById("theme");function label(){b.textContent=document.documentElement.dataset.theme==="dark"?"Light mode":"Dark mode"}label();b.onclick=()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==="dark"?"light":"dark";try{localStorage.setItem(key,document.documentElement.dataset.theme)}catch{}label()}})();''',encoding='utf-8')

# Bundle renderer assets so responses format without a CDN connection.
for source,name in [
 ('marked/lib/marked.umd.js','marked.umd.js'),
 ('marked/LICENSE','marked-LICENSE.txt'),
 ('dompurify/dist/purify.min.js','purify.min.js'),
 ('dompurify/LICENSE','dompurify-LICENSE.txt'),
 ('dompurify/LICENSE-MPL','dompurify-LICENSE-MPL.txt'),
]:
 source=APP/'node_modules'/source
 if source.exists():shutil.copyfile(source,PUBLIC/name)
 elif not (PUBLIC/name).exists():raise FileNotFoundError('Required bundled renderer asset: '+name)

NAV=[('/', 'Application lab'),('/learn.html','What you will learn'),('/run.html','How to run'),('/architecture.html','Architecture & workflow'),('/walkthrough.html','Code walkthrough')]
def document(path,title,subtitle,body,extra=''):
 nav=''.join(f'<a href="{url}"'+(' aria-current="page"' if url==path else '')+'>'+label+'</a>' for url,label in NAV)
 html='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Agent SDK LESSON 58 · '+escape(title)+'</title><link rel="stylesheet" href="/style.css"><link rel="stylesheet" href="/code-highlighting.css"></head><body><main><div class="brand"><a href="/">How <span>Claude Agent SDK</span> Works</a><span class="badge">LESSON 58 / DOCKER DEPLOYMENT</span></div><header class="hero"><div><div class="eyebrow">BUILD · DEPLOY · RESUME</div><h1>'+title+'</h1><p class="lead">'+subtitle+'</p></div><img src="/astronaut.png" alt="Course astronaut mascot"></header><nav class="nav" aria-label="Application sections">'+nav+'<button id="theme" type="button">Dark mode</button></nav>'+body+'<footer>CLAUDE AGENT SDK · LESSON 58 · CONTAINER · SERVICE · STORE<br>TypeScript · local runtime · API key stays on the server</footer></main><script src="/navigation.js"></script><script src="/prism.js"></script><script src="/prism-markup.min.js"></script><script src="/prism-sql.min.js"></script><script src="/prism-diff.min.js"></script><script src="/prism-yaml.min.js"></script><script src="/prism-markdown.min.js"></script><script src="/prism-python.min.js"></script><script src="/code-highlighting.js"></script><script src="/marked.umd.js"></script><script src="/purify.min.js"></script>'+extra+'</body></html>'
 (PUBLIC/('index.html' if path=='/' else path[1:])).write_text(html,encoding='utf-8')
def snippet(value,lang='typescript'):return '<pre><code class="language-'+lang+'">'+escape(value)+'</code></pre>'
def cards(items):return '<div class="grid">'+''.join(f'<article class="card"><span class="number">{i:02}</span><h3>{escape(a)}</h3><p>{escape(b)}</p></article>' for i,(a,b) in enumerate(items,1))+'</div>'
def actions(previous,next):return '<div class="actions">'+''.join(f'<a class="button" href="{p}">{t}</a>' for p,t in [previous,next])+'</div>'

exec(compile((APP/"scripts/lesson-content.py").read_text(encoding="utf-8"), str(APP/"scripts/lesson-content.py"), "exec"))
for page in PUBLIC.glob('*.html'):
 text=page.read_text(encoding='utf-8').replace('<script src="/code-highlighting.js">','<script src="/prism-docker.min.js"></script><script src="/code-highlighting.js">')
 page.write_text(text,encoding='utf-8')
